const body = $input.first().json.body || $input.first().json;
let urls = body.urls || body.urls_list || body.post_urls || body.url;

if (!urls) {
  throw new Error('Instagram post URLs are required. Send { "urls": ["https://www.instagram.com/p/XXXX"] } in the request body.');
}

if (typeof urls === 'string') {
  urls = [urls];
}

const formattedUrls = urls.map(u => {
  if (typeof u === 'string') return { url: u };
  if (u.url) return { url: u.url };
  return { url: String(u) };
});

return [{
  json: {
    urls: formattedUrls,
    url_count: formattedUrls.length,
    timestamp: new Date().toISOString()
  }
}];

const response = $input.first().json;

if (response.code !== 0) {
  return [{
    json: {
      error: 'CoreClaw API error: ' + (response.message || 'Unknown error'),
      request_id: response.request_id
    }
  }];
}

const dataList = (response.data && response.data.list) || [];
const headers = (response.data && response.data.headers) || [];

if (dataList.length === 0) {
  return [{
    json: {
      error: 'No posts found in CoreClaw response',
      count: 0
    }
  }];
}

const parsedPosts = dataList.map(post => {
  return {
    json: {
      post_id: post.id || post.pk || post.shortcode || '',
      shortcode: post.shortcode || post.code || '',
      image_url: post.image_url || post.display_url || post.thumbnail_src || '',
      video_url: post.video_url || '',
      is_video: post.is_video || post.media_type === 2 || false,
      caption: post.caption || post.caption_text || '',
      likes: post.like_count || post.likes || 0,
      comments: post.comment_count || post.comments || 0,
      timestamp: post.taken_at_timestamp || post.timestamp || post.created_time || '',
      permalink: post.permalink || (post.shortcode ? 'https://instagram.com/p/' + post.shortcode + '/' : ''),
      location: post.location ? (post.location.name || post.location) : ''
    }
  };
});

return parsedPosts;

